    responses:async()=>{const rows=await api('passports/'+current.id+'/requests');dialog('Proposte e richieste',rows.map(r=>html`<article class="gmpp-history"><strong>Richiesta #${r.id} · ${esc(r.state)}</strong><p>Scadenza: ${esc(r.expires_at)}</p>${Object.entries(r.proposal).map(([k,v])=>html`<p><strong>${esc(labels[k]||k)}</strong>: ${esc(v)}</p>`).join('')}${r.state==='answered'?html`${button('response-accept','Accetta nella bozza',false,html`data-id="${r.id}"`)}${button('response-reject','Rifiuta',false,html`data-id="${r.id}"`)}`:r.state==='open'?button('request-revoke','Revoca collegamento',false,html`data-id="${r.id}"`):''}</article>`).join('')||markup('<p>Nessuna richiesta.</p>'));},
    'response-accept':async el=>{current=await api('requests/'+el.dataset.id+'/review','POST',{accept:true,lock_version:Number(current.lock_version)});await editorView(current.id);notice('Proposta inserita nella bozza. La pubblicazione richiede una nuova revisione.');},
